package com.bank.decision;

import java.util.logging.*;

public class BuildVsBuyDemo {
    private static final Logger log = Logger.getLogger("Decision");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        BuildVsBuyAdvisor advisor = new BuildVsBuyAdvisor();

        // Email/SMS delivery: commodity, cheap to buy, urgent
        Capability email = new Capability("Email/SMS delivery",
            false, 500_000, 60_000, false, true, false);
        log.info(() -> advisor.recommend(email));

        // Fraud detection: core differentiator, team has expertise, uses bank's data
        Capability fraud = new Capability("Fraud detection model",
            true, 800_000, 900_000, true, false, false);
        log.info(() -> advisor.recommend(fraud));

        // Core ledger: sensitive data, sovereignty + lock-in risk
        Capability ledger = new Capability("Core banking ledger",
            true, 2_000_000, 1_500_000, true, false, true);
        log.info(() -> advisor.recommend(ledger));
    }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
